func TestReview6520RegionAndAuthRollbackOnConfigWriteFailure(t *testing.T) {
	for _, hadPreference := range []bool{false, true} {
		name := "without-previous-preference"
		if hadPreference {
			name = "with-previous-preference"
		}
		t.Run(name, func(t *testing.T) {
			source, target := t.TempDir(), t.TempDir()
			oldPreference := `{"version":1,"regions":{"prod":"en"}}`
			newPreference := `{"version":1,"regions":{"prod":"cn"}}`
			writeRefreshFixture(t, filepath.Join(source, "config.yaml"), "defaultModel: minimax/replacement\n")
			writeRefreshFixture(t, filepath.Join(source, "auth", "token"), "replacement-token")
			writeRefreshFixture(t, filepath.Join(source, nativeRegionPreference), newPreference)
			writeRefreshFixture(t, filepath.Join(target, "auth", "token"), "working-token")
			if hadPreference {
				writeRefreshFixture(t, filepath.Join(target, nativeRegionPreference), oldPreference)
			}
			// The final config rename fails after auth and preference publication.
			writeRefreshFixture(t, filepath.Join(target, "config.yaml", "previous"), "unchanged-config-path")
			if err := refreshProfileCredentials(context.Background(), target, source); err == nil {
				t.Fatal("config write unexpectedly succeeded")
			}
			for path, want := range map[string]string{
				filepath.Join(target, "auth", "token"):             "working-token",
				filepath.Join(target, "config.yaml", "previous"):   "unchanged-config-path",
				filepath.Join(source, "auth", "token"):             "replacement-token",
				filepath.Join(source, nativeRegionPreference):     newPreference,
			} {
				got, err := os.ReadFile(path)
				if err != nil || string(got) != want {
					t.Fatalf("rollback changed %s: %q, %v; want %q", path, got, err, want)
				}
			}
			preference := filepath.Join(target, nativeRegionPreference)
			if hadPreference {
				got, err := os.ReadFile(preference)
				if err != nil || string(got) != oldPreference {
					t.Fatalf("previous region preference was not restored: %q, %v; want %s", got, err, oldPreference)
				}
			} else if _, err := os.Lstat(preference); !os.IsNotExist(err) {
				t.Fatalf("failed refresh left a new region preference behind: %v", err)
			}
		})
	}
}
