+// Uses the official 0.6.5 bundle unchanged, except for appending one export
+// to a temporary adjacent COPY so its native CrossProcessLock can own a lock.
+import { randomBytes } from 'node:crypto';
+import { readFile, rm, writeFile } from 'node:fs/promises';
+import path from 'node:path';
+import { pathToFileURL } from 'node:url';
+
+const [mode, packageDir, profile, probeLimit = '1500'] = process.argv.slice(2);
+const manifest = JSON.parse(await readFile(path.join(packageDir, 'package.json'), 'utf8'));
+if (manifest.name !== '@minimax-ai/code' || manifest.version !== '0.6.5') throw new Error('Requires official @minimax-ai/code@0.6.5.');
+const original = path.join(packageDir, 'chunks', 'chunk-JL7ZXU6T.js');
+const source = await readFile(original, 'utf8');
+if (!source.includes('w=class{lockPath;staleMs;retries;')) throw new Error('Native CrossProcessLock was not found.');
+const instrumented = path.join(packageDir, 'chunks', `.ao-review-authlock-${process.pid}-${randomBytes(6).toString('hex')}.mjs`);
+await writeFile(instrumented, `${source}\nexport { w as AOReviewCrossProcessLock };\n`, { flag: 'wx', mode: 0o600 });
+let forceExit = false;
+try {
+  const native = await import(pathToFileURL(instrumented).href);
+  const namespace = native.b({ dataDir: profile, buildEnv: 'prod', region: 'en' });
+  const owner = new native.AOReviewCrossProcessLock(namespace.lockPath);
+  if (mode === 'hold') {
+    let release;
+    const released = new Promise(resolve => { release = resolve; });
+    process.stdin.once('end', release);
+    process.stdin.resume();
+    await owner.withLock(async () => {
+      console.log(JSON.stringify({ ready: true, lockDirectory: `${namespace.lockPath}.lock`, staleMs: owner.staleMs, retries: owner.retries }));
+      await released;
+    });
+  } else if (mode === 'probe') {
+    const started = performance.now();
+    let timer;
+    // c is MiniMax's actual namespace initializer, including both its legacy
+    // and scoped native auth locks. No model request or OAuth service is used.
+    const result = await Promise.race([
+      native.c(namespace).then(() => ({ outcome: 'completed' }), error => ({ outcome: 'error', code: error.code, message: error.message })),
+      new Promise(resolve => { timer = setTimeout(() => resolve({ outcome: 'bounded-timeout' }), Number(probeLimit)); }),
+    ]);
+    clearTimeout(timer);
+    console.log(JSON.stringify({ ...result, elapsedMs: Math.round(performance.now() - started), lockDirectory: `${namespace.lockPath}.lock`, staleMs: owner.staleMs, retries: owner.retries }));
+    forceExit = result.outcome === 'bounded-timeout';
+  } else {
+    throw new Error('Mode must be hold or probe.');
+  }
+} finally {
+  await rm(instrumented, { force: true });
+}
+// A bounded probe must not leave native retry timers running.
+if (forceExit) process.exit(0);
